from pathlib import Path
import json,hashlib,html,xml.etree.ElementTree as E
from PIL import Image
H=Path(__file__).resolve().parent
rows=json.loads((H/'previews.json').read_text())
hashes=json.loads((H/'source_hashes.json').read_text())
assert all(hashlib.sha256(Path(p).read_bytes()).hexdigest()==h for p,h in hashes.items())
qa=[]
for r in rows:
 src=E.parse(r['source']).getroot(); dst=E.parse(r['output']).getroot()
 old=[e.attrib for e in src.iter() if e.get('data-comparative-person')]
 new=[e.attrib for e in dst.iter() if e.get('data-comparative-person')]
 assert old==new
 im=Image.open(Path('/private/tmp/task9_full_figure_preview_20261119')/(r['id']+'.png')).convert('RGBA');bbox=im.getchannel('A').getbbox()
 assert bbox and bbox[0]>0 and bbox[1]>0 and bbox[2]<512 and bbox[3]<512,(r['id'],bbox)
 qa.append({'id':r['id'],'visually_checked':True,'result':'pass for preview','annotation_primitives_preserved':r['annotation_primitives'],'parent_transforms_and_opacity_unchanged':True,'rendered_alpha_bbox':bbox,'output_sha256':hashlib.sha256(Path(r['output']).read_bytes()).hexdigest()})
(H/'verification.json').write_text(json.dumps({'preview_count':len(rows),'original_files_hash_verified_unchanged':len(hashes),'published':False,'reviews':qa},indent=2))
css='''*{box-sizing:border-box}body{margin:0;background:#f4f6f9;color:#182634;font:17px system-ui,sans-serif}main{max-width:1150px;margin:auto;padding:28px}h1{font-size:30px;margin-bottom:10px}p{line-height:1.55;max-width:950px}.notice{padding:14px 18px;background:#fff4d5;border-radius:10px}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0}button{font:inherit;padding:9px 18px;border:1px solid #8194a5;border-radius:7px;background:white;cursor:pointer}button[aria-pressed=true]{background:#234a70;color:white}article{padding:20px;background:white;border-radius:12px;margin:22px 0;box-shadow:0 2px 8px #0001}article h2{margin:0 0 12px;font-size:22px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}figure{margin:0}figcaption{font-weight:650;padding:9px 0}img{width:100%;display:block;background:#e5edf5;border-radius:8px}.note{margin-bottom:0;color:#43566a}small{font-size:14px}@media(max-width:600px){main{padding:16px}.pair{gap:8px}article{padding:12px}figcaption{font-size:14px}}'''
parts=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>3D and Kawaii — full-figure previews</title><style>'+css+'</style><main><h1>3D and Kawaii: full-figure previews</h1><p class="notice"><strong>Eight examples for your review only.</strong> No People or Library images have been changed. The full rollout has not started.</p><p>Complete figures replace the earlier head-and-body adaptations in these examples. Flat outlined, Mulberry and Simple anime will keep their existing comparative figures. Sommi and Sommi clothed remain completed and excluded.</p><p>The arrows and star keep their original geometry. Dirt marks are moved onto the new clothing, odour marks sit beside the heads, and the crossed-out water drop is raised clear of the wider head. Sparkles, puddles, dry-ground marks, sun, relative heights and comparison-figure fading are retained.</p><div class="controls"><button aria-pressed="true" data-filter="all">Both styles</button><button aria-pressed="false" data-filter="3D animated cartoon">3D</button><button aria-pressed="false" data-filter="Kawaii">Kawaii</button></div>']
for r in rows:
 esc=html.escape; gender='male' if r['gender']=='M' else 'female'
 parts.append(f'<article data-style="{esc(r["style"])}" id="{r["id"]}"><h2>{esc(r["style"])} — {r["concept"]} ({gender})</h2><div class="pair"><figure><figcaption>Before — existing comparative</figcaption><img src="{esc(Path(r["source"]).as_uri())}" alt="Existing {r["concept"]}"></figure><figure><figcaption>Preview — complete figures</figcaption><img src="{esc(Path(r["output"]).name)}" alt="Full-figure {r["concept"]} preview"></figure></div><p class="note">{esc(r["note"])}</p></article>')
parts.append('<p><strong>Scope of these examples:</strong> cleaner, cleanest, taller and wetter in both styles, with male and female figures. These demonstrate standing and height-comparison compositions. Pose-specific symbols such as faster and stronger will need appropriate poses; these examples do not validate replacing those poses with standing figures.</p><p><small>All eight previews visually checked. Every source annotation shape is retained; all 12 source files have unchanged hashes. Preview SVGs use complete figures from the saved Pronoun SVGs. No regeneration or compression was performed. <a href="verification.json">Verification</a> · <a href="previews.json">Per-file details</a></small></p></main><script>document.querySelectorAll("button[data-filter]").forEach(b=>b.onclick=()=>{document.querySelectorAll("button[data-filter]").forEach(x=>x.setAttribute("aria-pressed",String(x===b)));document.querySelectorAll("article").forEach(a=>a.hidden=b.dataset.filter!=="all"&&a.dataset.style!==b.dataset.filter)})</script></html>')
(H/'index.html').write_text('\n'.join(parts))
(H/'decision.json').write_text(json.dumps({'date':'2026-11-19','full_figures':['3D animated cartoon','Kawaii'],'keep_existing_figures':['Flat outlined','Mulberry','Simple anime'],'full_figure_scope':96,'retain_existing_scope':144,'preview_only':True,'rollout_requires_preview_approval':True,'completed_excluded':['Sommi','Sommi clothed'],'non_people_excluded':True},indent=2))
print(json.dumps({'previews_verified':len(qa),'sources_unchanged':len(hashes),'review':str(H/'index.html')}))
